import{_ as i,c as t,o as n,ae as o}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"WHITE HOUSE INITIATIVE TO PROMOTE EXCELLENCE AND INNOVATION AT HISTORICALLY BLACK COLLEGES AND UNIVERSITIES","description":"","frontmatter":{"title":"WHITE HOUSE INITIATIVE TO PROMOTE EXCELLENCE AND INNOVATION AT HISTORICALLY BLACK COLLEGES AND UNIVERSITIES","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities/","publishDate":"2025-04-23T18:40:32-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-23-white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities.md","filePath":"executive-orders/2025-04-23-white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities.md"}'),s={name:"executive-orders/2025-04-23-white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities.md"};function a(l,e,r,c,d,h){return n(),t("div",null,e[0]||(e[0]=[o('<h1 id="white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities" tabindex="-1">WHITE HOUSE INITIATIVE TO PROMOTE EXCELLENCE AND INNOVATION AT HISTORICALLY BLACK COLLEGES AND UNIVERSITIES <a class="header-anchor" href="#white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities" aria-label="Permalink to &quot;WHITE HOUSE INITIATIVE TO PROMOTE EXCELLENCE AND INNOVATION AT HISTORICALLY BLACK COLLEGES AND UNIVERSITIES&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/white-house-initiative-to-promote-excellence-and-innovation-at-historically-black-colleges-and-universities/</a></p><p>Published: Wednesday, April 23, 2025</p><ul><li>Establishes the <strong>White House Initiative on Historically Black Colleges and Universities (HBCUs)</strong> to enhance the role of HBCUs in providing quality education and economic opportunity.</li><li>The Initiative will: <ul><li><strong>Work with various partners</strong> including federal agencies, private employers, and educational organizations to strengthen HBCUs.</li><li>Focus on two key missions: <ul><li><strong>Enhancing private-sector involvement</strong> in: <ul><li>Institutional planning and financial management for HBCUs.</li><li>Upgrading technology and infrastructure.</li><li>Offering professional development for HBCU students in high-growth industries.</li></ul></li><li><strong>Improving HBCUs’ capabilities</strong> by: <ul><li>Supporting implementation of the <strong>HBCU PARTNERS Act</strong>.</li><li>Advancing priorities regarding innovation and excellence in collaboration with HBCU leaders.</li><li>Fostering partnerships to promote research and program excellence at HBCUs.</li><li>Addressing student success, affordability, and retention.</li><li>Encouraging state funding for 1890 Land-Grant Institutions.</li><li>Collaborating on federal funding access and improving competitiveness for research funding.</li><li>Hosting an annual <strong>White House Summit on HBCUs</strong> to address related issues.</li></ul></li></ul></li></ul></li><li>Establishes the <strong>President’s Board of Advisors on HBCUs</strong> within the Department of Education to advise the Initiative and support its mission.</li><li>The <strong>Executive Director of the Initiative</strong> will submit an annual progress report to the President evaluating the impact on HBCUs and recommending improvements.</li><li>Revokes <strong>Executive Order 14041</strong> and directs the termination of the <strong>HBCUs and Minority Serving Institutions Advisory Council</strong> within 14 days.</li><li>Defines HBCUs as those listed under <strong>34 C.F.R. 608.2</strong> and ensures that the order does not affect existing legal authorities or create enforceable rights against the government.</li></ul>',4)]))}const v=i(s,[["render",a]]);export{g as __pageData,v as default};
